<template>
  <div class="user-profile-container">
    <!-- Cover Section -->
    <div class="cover-section">
      <div class="cover-image-wrapper">
        <v-img
          ref="coverImage"
          class="cover-image"
          :src="placeholderImage"
          :lazy-src="placeholderImage"
          height="300"
          gradient="to bottom, rgba(0,0,0,0) 0%, rgba(0,0,0,0.3) 100%"
        >
          <template v-slot:placeholder>
            <v-row class="fill-height ma-0" align="center" justify="center">
              <v-progress-circular indeterminate color="grey lighten-5"></v-progress-circular>
            </v-row>
          </template>
        </v-img>

        <!-- Cover Overlay Actions -->
        <div class="cover-overlay">
          <v-btn
            icon
            dark
            class="cover-action-btn"
            @click="loadRealImage"
          >
            <v-icon>mdi-refresh</v-icon>
          </v-btn>
        </div>
      </div>

      <!-- Profile Avatar -->
      <div class="avatar-section">
        <div class="avatar-wrapper">
          <v-avatar size="180" class="profile-avatar">
            <v-img
              :src="getSchPicture || placeholderImage"
              @error="handleImageError"
            >
              <template v-slot:placeholder>
                <v-icon size="80" color="grey lighten-2">mdi-account</v-icon>
              </template>
            </v-img>
          </v-avatar>

          <!-- Online Status Badge -->
          <v-badge
            dot
            color="green"
            overlap
            bottom
            class="online-status-badge"
          ></v-badge>
        </div>

        <!-- User Name -->
        <h1 class="user-name">{{ userName }}</h1>
        <p class="user-handle">@{{ userName ? userName.toLowerCase().replace(/\s/g, '_') : '' }}</p>

        <!-- Stats Row -->
        <div class="stats-row">
          <div class="stat-item">
            <span class="stat-value">{{ posts.length }}</span>
            <span class="stat-label">Posts</span>
          </div>
          <div class="stat-divider"></div>
          <div class="stat-item">
            <span class="stat-value">{{ getRandomStat(50, 500) }}</span>
            <span class="stat-label">Friends</span>
          </div>
          <div class="stat-divider"></div>
          <div class="stat-item">
            <span class="stat-value">{{ getRandomStat(10, 100) }}</span>
            <span class="stat-label">Photos</span>
          </div>
        </div>
      </div>
    </div>

    <!-- Action Buttons Section -->
    <div class="actions-section">
      <!-- Friend Request Actions (when other sent request) -->
      <div v-if="isOtherSent" class="friend-request-actions">
        <v-btn
          color="success"
          dark
          depressed
          rounded
          large
          class="action-btn accept-btn"
          @click="addFriend($route.params.id)"
          :loading="loadingAccept"
        >
          <v-icon left>mdi-account-check</v-icon>
          Accept
        </v-btn>

        <v-btn
          color="error"
          dark
          depressed
          outlined
          rounded
          large
          class="action-btn reject-btn"
          @click="removeRequestOneAndReset($route.params.id)"
          :loading="loadingDecline"
        >
          <v-icon left>mdi-account-remove</v-icon>
          Decline
        </v-btn>
      </div>

      <!-- Normal Actions -->
      <div v-else class="normal-actions">
        <!-- Add Friend Button -->
        <v-btn
          v-if="userId !== paramsId.id && !isFriend"
          color="primary"
          dark
          depressed
          rounded
          large
          class="action-btn add-friend-btn"
          @click="addRequest(paramsId.id)"
          :loading="loadingAdd"
        >
          <v-icon left>{{ requestPending ? 'mdi-clock-outline' : 'mdi-account-plus' }}</v-icon>
          {{ isFriendRequestExist }}
        </v-btn>

        <!-- Friend Button with Menu -->
        <v-menu
          v-if="isFriend"
          offset-y
          left
          transition="slide-y-transition"
        >
          <template v-slot:activator="{ on, attrs }">
            <v-btn
              color="green"
              dark
              depressed
              rounded
              large
              class="action-btn friend-btn"
              v-bind="attrs"
              v-on="on"
            >
              <v-icon left>mdi-account-check</v-icon>
              Friend
              <v-icon right small>mdi-chevron-down</v-icon>
            </v-btn>
          </template>

          <v-list dense>
            <v-list-item @click="removeFriend" class="remove-friend-item">
              <v-list-item-icon>
                <v-icon color="error">mdi-account-remove</v-icon>
              </v-list-item-icon>
              <v-list-item-title class="error--text">Unfriend</v-list-item-title>
            </v-list-item>
          </v-list>
        </v-menu>
      </div>
    </div>

    <!-- Posts Section - 3 per row -->
    <v-container fluid class="posts-container">
      <v-row justify="center">
        <v-col 
          cols="12" 
          sm="6" 
          md="4" 
          v-for="post in posts" 
          :key="post._id"
          class="post-col"
        >
          <div @click="inPostClick(post)" class="post-wrapper">
            <!-- SAME my-post format as original -->
            <my-post
              class="responsive-post"
              :image="urls + '/static/' + post._id + '.PNG'"
              :name="post.text"
              :id="post._id"
              :commentsArr="post.comments"
              :likeNumber="post.likes.length"
              :likesArr="post.likes"
              :owner="post.owner"
              :date="post.date"
              :isEdit2="false"
              :ownerId="$route.params.id"
            >
            </my-post>
          </div>
        </v-col>
      </v-row>
    </v-container>

    <!-- Snackbar -->
    <v-snackbar
      :value="snackbar"
      @input="snackbar = $event"
      :color="snackbarColor"
      :timeout="3000"
      top
