<script>
import serverUrl from '../../config';
import { mapActions, mapGetters } from "vuex";
import axios from "axios";
import * as types from "../../store/types";
import Post from "../post/post";
import io from "socket.io-client";

global.jQuery = require("jquery");
var $ = global.jQuery;
window.$ = $;

export default {
  name: 'UserProfile',
  props: ["image"],

  data() {
    return {
      userId: localStorage.getItem("userID"),
      img: null,
      isFriend: false,
      requestPending: false,
      index: 0,
      socket: io(serverUrl, {
        query: { token: localStorage.getItem("token") },
      }),
      userName: null,
      isOtherSent: false,
      urls: serverUrl,
      placeholderImage: require('@/assets/avatar.png'),
      realImageUrl: "https://picsum.photos/510/300?random",

      // Loading states
      loadingAccept: false,
      loadingDecline: false,
      loadingAdd: false,

      // Snackbar
      snackbar: false,
      snackbarText: '',
      snackbarColor: 'success',
      snackbarIcon: 'mdi-check-circle',
    };
  },

  computed: {
    ...mapGetters({
      initRequest: types.INITIAL_REQUEST,
    }),

    paramsId() {
      return this.$route.params;
    },

    getSchPicture() {
      return this.$store.getters.getUserSrchPic;
    },

    isFriendRequestExist() {
      return this.requestPending ? "Request Pending" : "Add Friend";
    },

    posts() {
      let fArr = [];
      for (let i = 0; i < this.$store.getters.getUserPosgts.length; i++) {
        fArr.push(this.$store.getters.getUserPosgts[i][0]);
      }
      let unique = [...new Set(fArr)];
      return unique;
    },
  },

  created() {
    this.socket.on('edit-post', (post) => {
      this.$store.commit(types.EDIT_USER_POST, post);
      for (let i = 0; i < this.posts.length; i++) {
        if (this.posts[i]._id == post.id) {
          this.posts[i].text = post.text;
        }
      }
    });

    this.socket.on('delete-post', (post) => {
      this.$store.commit(types.DELETE_USER_POST, post);
      for (let i = 0; i < this.posts.length; i++) {
        if (this.posts[i]._id == post.postid) {
          this.posts.splice(i, 1);
        }
      }
    });

    this.$store.dispatch("getUserSearchPic", this.$route.params.id);

    setTimeout(() => {
      this.submitFriend;
    }, 1000);

    // Check friendship status
    axios
      .post(
        this.urls + "/friend-request/remove-submitted-user",
        { id: this.$route.params.id },
        { headers: { authorization: localStorage.getItem("token") } }
      )
      .then((res) => {
        this.isFriend = res.data.success;
      });

    // Check pending request
    axios
      .post(
        this.urls + "/friend-request/request-pending",
        { id: this.$route.params.id },
        { headers: { authorization: localStorage.getItem("token") } }
      )
      .then((value) => {
        this.requestPending = value.data;
      });

    // Get user posts
    this.$store.dispatch(types.GET_USER_POSTS, { index: 0, id: this.$route.params.id });
    this.$store.dispatch(types.CHECK_MATCH_ID, localStorage.getItem('userID'));

    // Get username
    axios.post(
      this.urls + '/users/get-username-profile/' + this.paramsId.id,
      { 1: 1 },
      { headers: { authorization: localStorage.getItem("token") } }
    ).then((res) => {
      this.userName = res.data;
    });

    // Check if other sent request
    axios
      .post(
        this.urls + "/friend-request/is-other-already-sent-reques",
        { id: this.$route.params.id },
        { headers: { authorization: localStorage.getItem("token") } }
      )
      .then((res) => {
        this.isOtherSent = res.data.success;
      });
  },

  methods: {
    addRequest(id) {
      this.loadingAdd = true;
      axios
        .post(
          this.urls + "/friend-request/new-request",
          { id: id },
          { headers: { authorization: localStorage.getItem("token") } }
        )
        .then((response) => {
          if (response.data.success) {
            this.requestPending = true;
            this.socket.emit("new-fr-req", id);
            this.socket.emit("get-fr-req-data", id);
            this.showSnackbar('Friend request sent!', 'success', 'mdi-check-circle');
          }
        })
        .finally(() => {
          this.loadingAdd = false;
        });
    },

    ...mapActions({
      request: types.GET_FRIEND_REQUEST,
      removeRequestOne: types.REMOVE_ADD_REQUEST_ONE
    }),

    scroll() {
      let t = this;
      $(window).scroll(function () {
        if ($(window).scrollTop() + $(window).height() > $(document).height() - 100) {
          t.index += 2;
          t.$store.dispatch(types.GET_USER_POSTS, { index: t.index, id: t.$route.params.id });
        }
      });
    },

    inPostClick(post) {
      console.log("Posts.vue inPostClick", post);
    },

    removeFriend() {
      this.isFriend = false;
      this.requestPending = false;
      this.socket.emit('remove-friend', { id: this.$route.params.id });
      this.showSnackbar('Friend removed', 'info', 'mdi-account-remove');
    },

    addFriend(id) {
      this.loadingAccept = true;
      this.isOtherSent = false;
      this.isFriend = true;
      this.$store.dispatch(types.SUBMIT_FRIEND_REQUEST, id).then(() => {
        this.$store.commit(types.REMOVE_ADD_REQUEST, id);
        this.showSnackbar('Friend request accepted!', 'success', 'mdi-check-circle');
      }).finally(() => {
        this.loadingAccept = false;
      });
    },

    removeRequestOneAndReset(id) {
      this.loadingDecline = true;
      this.isOtherSent = false;
      this.isFriend = false;
      this.removeRequestOne(id).then(() => {
        this.showSnackbar('Request declined', 'info', 'mdi-close-circle');
      }).finally(() => {
        this.loadingDecline = false;
      });
    },

    loadRealImage() {
      const img = this.$refs.coverImage;
      if (!img) return;

      const realSrc = this.realImageUrl;
      const tempImg = new Image();
      tempImg.src = realSrc;

      tempImg.onload = () => {
        img.src = realSrc;
      };

      tempImg.onerror = () => {
        console.log("Failed to load image, using placeholder");
      };
    },

    handleImageError(event) {
      event.target.src = this.placeholderImage;
    },

    showSnackbar(text, color, icon) {
      this.snackbarText = text;
      this.snackbarColor = color;
      this.snackbarIcon = icon;
      this.snackbar = true;
    },

    getRandomStat(min = 10, max = 200) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    },

    formatDate(date) {
      if (!date) return 'Just now';
      const d = new Date(date);
      const now = new Date();
      const diff = Math.floor((now - d) / 1000);

      if (diff < 60) return 'Just now';
      if (diff < 3600) return Math.floor(diff / 60) + 'm ago';
      if (diff < 86400) return Math.floor(diff / 3600) + 'h ago';
      if (diff < 604800) return Math.floor(diff / 86400) + 'd ago';
      return d.toLocaleDateString();
    }
  },

  mounted() {
    this.scroll();
    this.loadRealImage();
  },

  components: {
    "my-post": Post,
  },

  beforeDestroy() {
    this.$router.go();
  },
};
</script>

